"use client";

import type { ComponentPropsWithoutRef, FC, ReactNode } from "react";
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from "@/cn/ui/dialog.js";
import { Button, } from "@/cn/ui/button.js";
import type { PropsOf } from "@/types/index.js";

export interface ConfirmDialogProps extends ComponentPropsWithoutRef<typeof Dialog> {
    confirmBtnText?: string;
    cancelBtnText?: string;
    title?: string;
    message: ReactNode;
    onConfirm?: () => void;
    onCancel?: () => void;
    confirmBtnProps?: PropsOf<typeof Button>;
    cancelBtnProps?: PropsOf<typeof Button>;
}

export const ConfirmDialog: FC<ConfirmDialogProps> = ({
    confirmBtnText,
    cancelBtnText,
    title,
    message,
    onConfirm,
    onCancel,
    confirmBtnProps,
    cancelBtnProps,
    onOpenChange,
    ...dialogProps
}) => {
    return (
        <Dialog
            onOpenChange={(open) => {
                onOpenChange?.(open);
                if (!open) onCancel?.();
            }}
            {...dialogProps}
        >
            <DialogContent className="sm:max-w-md">
                {title && (
                    <DialogHeader>
                        <DialogTitle>{title}</DialogTitle>
                    </DialogHeader>
                )}
                <div className="py-2">{message}</div>
                <DialogFooter>
                    {cancelBtnText !== "" && (
                        <Button
                            variant="outline"
                            {...cancelBtnProps}
                            onClick={(e) => {
                                cancelBtnProps?.onClick?.(e);
                                if (!e.defaultPrevented) onCancel?.();
                            }}
                        >
                            {cancelBtnText ?? "Cancel"}
                        </Button>
                    )}
                    <Button
                        variant="destructive"
                        {...confirmBtnProps}
                        onClick={(e) => {
                            confirmBtnProps?.onClick?.(e);
                            if (!e.defaultPrevented) onConfirm?.();
                        }}
                    >
                        {confirmBtnText ?? "Ok"}
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
};

"use client";

import { useCallback, useMemo, useRef, useState, type ReactNode } from "react";
import { ConfirmDialog, type ConfirmDialogProps } from "./confirm-dialog";

interface UseConfirmDialogOptions {
    baseDialogOptions?: Partial<ConfirmDialogProps>;
}

interface UseConfirmDialogResult {
    /**
     * @returns A promise that resolves to true if confirmed, false otherwise.
     */
    confirm: (dialogProps: Partial<ConfirmDialogProps>) => Promise<boolean>;
    /**
     * Indicates if any confirm dialog is currently active.
     */
    isActive: boolean;
    /**
     * The React nodes for the confirm dialogs.
     */
    confirmModals: ReactNode;
}

export function useConfirmDialog({
    baseDialogOptions,
}: UseConfirmDialogOptions = {}): UseConfirmDialogResult {
    const dialogs = useRef<Record<string, ConfirmDialogProps>>({});
    const [dialogsOpen, setDialogsOpen] = useState<Record<string, boolean>>({});

    const isActive = useMemo(() => Object.values(dialogsOpen).some(Boolean), [dialogsOpen]);

    const confirm = useCallback(
        (dialogProps: Partial<ConfirmDialogProps>) => {
            const id = crypto.randomUUID();

            return new Promise<boolean>((resolve) => {
                setDialogsOpen((prev) => ({ ...prev, [id]: true }));

                const close = () => {
                    setDialogsOpen((prev) => ({ ...prev, [id]: false }));
                    setTimeout(() => {
                        delete dialogs.current[id];
                    }, 300);
                };

                const handleConfirm = () => {
                    close();
                    baseDialogOptions?.onConfirm?.();
                    dialogProps.onConfirm?.();
                    resolve(true);
                };

                const handleCancel = () => {
                    close();
                    baseDialogOptions?.onCancel?.();
                    dialogProps.onCancel?.();
                    resolve(false);
                };

                dialogs.current[id] = {
                    message: "Are you sure?",
                    ...baseDialogOptions,
                    ...dialogProps,
                    onConfirm: handleConfirm,
                    onCancel: handleCancel,
                };
            });
        },
        [baseDialogOptions],
    );

    const confirmModals = (
        <>
            {Object.entries(dialogs.current).map(([id, props]) => (
                <ConfirmDialog key={id} {...props} open={dialogsOpen[id] ?? false} />
            ))}
        </>
    );

    return { confirm, isActive, confirmModals };
}
